  function makeMagazine(id,loaded=false){const d=C[id];if(!d||d.category!=='magazine')return id;return {id,uid:itemUid(),contents:loaded?Array.from({length:d.capacity||0},()=>weaponDefaultAmmo(d.weapons?.[0])||[...Object.keys(C)].find(a=>C[a]?.category==='ammo'&&C[a]?.caliber===d.caliber)):[]}}
  function makeAmmoStack(id,rounds=null){const d=C[id];if(!d||d.category!=='ammo')return id;return {id,uid:itemUid(),rounds:Math.max(0,Math.min(d.stackRounds||60,Number(rounds??d.stackRounds??60)))}}
  function normalizeItemRef(ref,legacyLoaded=true){const id=itemId(ref),d=C[id];if(!d)return ref;if(d.category==='magazine'){if(typeof ref==='object'&&Array.isArray(ref.contents))return {id,uid:ref.uid||itemUid(),contents:ref.contents.filter(a=>C[a]?.category==='ammo'&&C[a]?.caliber===d.caliber).slice(-(d.capacity||0))};const ammo=weaponDefaultAmmo(d.weapons?.[0]);return {id,uid:itemUid(),contents:legacyLoaded&&ammo?Array.from({length:d.capacity||0},()=>ammo):[]}}if(d.category==='ammo'){if(typeof ref==='object'&&Number.isFinite(Number(ref.rounds)))return {id,uid:ref.uid||itemUid(),rounds:Math.max(0,Math.min(d.stackRounds||60,Number(ref.rounds)))};return makeAmmoStack(id)}return id}
  function inventoryRecordRef(rec){const id=rec?.item_id;if(!id)return null;const data=rec?.item_data&&typeof rec.item_data==='object'?rec.item_data:{};return normalizeItemRef({id,...data},false)}
