  function defaultMagazineForWeapon(id){return {makarov:'mag_pm_8',glock17:'mag_g17_17',pistol1911:'mag_1911_8',mp5:'mag_mp5_30',ak74:'mag_ak74_30',m4a1:'mag_m4_30',saiga12:'mag_saiga_8',vector:'mag_vector_25'}[id]||null}
