  function closePanel(id){$(id)?.classList.add('hidden');if(id==='settingsPanel')settingsOpen=false;if(id==='inventoryPanel')inventoryOpen=false;if(id==='lootPanel'){lootOpen=false;lootSource=null}if(id==='mapPanel')mapOpen=false;if(id==='stashPanel')stashOpen=false;if(id==='customizationPanel')customizationOpen=false;if(id==='adminPanel')adminOpen=false;if(id==='magazinePanel'){magazineOpen=false;magazineManagerRef=null}resumePointer()}
