  function closeAllGameplayPanels(){if(inventoryOpen){$('inventoryPanel').classList.add('hidden');inventoryOpen=false}if(lootOpen){$('lootPanel').classList.add('hidden');lootOpen=false;lootSource=null}if(mapOpen){$('mapPanel').classList.add('hidden');mapOpen=false}if(stashOpen){$('stashPanel')?.classList.add('hidden');stashOpen=false}if(customizationOpen){$('customizationPanel')?.classList.add('hidden');customizationOpen=false}if(adminOpen){$('adminPanel')?.classList.add('hidden');adminOpen=false}if(magazineOpen){$('magazinePanel')?.classList.add('hidden');magazineOpen=false;magazineManagerRef=null}}
  function toggleInventory(){if(actionBusy){toast('ACTION IN PROGRESS');return}if(!['raid','bunker'].includes(sceneMode))return;if(inventoryOpen){closePanel('inventoryPanel');return}closeAllGameplayPanels();inventoryOpen=true;renderInventory();$('inventoryPanel').classList.remove('hidden');releasePointer();setTimeout(()=>{previewEngine?.resize();rebuildCharacterPreview()},0)}
  function openMapPanel(){if(sceneMode!=='bunker')return;closeAllGameplayPanels();mapOpen=true;renderMaps();$('mapPanel').classList.remove('hidden');releasePointer()}
  function openLoot(source){if(!source||playerDead)return;closeAllGameplayPanels();lootSource=source;lootOpen=true;renderLoot();$('lootPanel').classList.remove('hidden');releasePointer()}
  function renderMaps(){$('mapCards').innerHTML=Object.entries(MAPS).map(([id,m])=>`<button class="map-card ${selectedMapId===id?'selected':''}" data-map="${id}"><div class="map-art"></div><div class="map-info"><span>${m.code}</span><h3>${m.name}</h3><p>${m.description}</p></div><div class="map-meta"><div><span>THREAT</span><b>${m.difficulty}</b></div><div><span>PRIMARY LOOT</span><b>${m.loot}</b></div></div></button>`).join('');document.querySelectorAll('.map-card').forEach(b=>b.addEventListener('click',()=>{selectedMapId=b.dataset.map;$('selectedMapName').textContent=MAPS[selectedMapId].name.toUpperCase();renderMaps()}));$('selectedMapName').textContent=MAPS[selectedMapId].name.toUpperCase()}
  function itemIcon(ref){const id=itemId(ref);return `assets/icons/${C[id]?id:'unknown'}.svg`}
  function gearSlotForItem(ref){const id=itemId(ref);if(WEAPONS[id])return WEAPONS[id].slot;const meta=gearMeta(id);if(meta.type==='plate')return plateSlotForItem(id)||'front_plate';if(meta.type==='softArmor'||meta.type==='plateCarrier')return'armor';if(meta.type==='helmet')return'head';if(['tactical_gloves','work_gloves','winter_gloves'].includes(id))return'hands';if(meta.type==='rig')return'rig';if(meta.type==='backpack')return'backpack';return null}
  function renderEquipmentSlotActions(){for(const slot of ['head','hands','armor','front_plate','back_plate','rig','backpack','primary','secondary']){const boxEl=document.querySelector(`.equip-slot[data-slot="${slot}"]`);if(!boxEl)continue;boxEl.querySelector('.equip-actions')?.remove();if(!equipment[slot])continue;const actions=document.createElement('div');actions.className='equip-actions';actions.innerHTML=`<button type="button" data-unequip-slot="${slot}">UNEQUIP</button>`;boxEl.appendChild(actions)}document.querySelectorAll('[data-unequip-slot]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();if(sceneMode==='bunker')unequipBunkerSlot(b.dataset.unequipSlot);else unequipRaidSlot(b.dataset.unequipSlot)}))}
  function inventoryContainer(name){if(sceneMode==='bunker')return name==='rig'?preparedRig():name==='pockets'?preparedPockets():preparedBag();return name==='rig'?fieldRigItems:name==='pockets'?fieldPocketItems:fieldItems}
  function fieldContainer(name){return inventoryContainer(name)}
  function fieldContainerLimit(name){return name==='rig'?rigSlotCount():name==='pockets'?4:backpackSlotCount()}
  function canMoveToFieldContainer(ref,name){const a=fieldContainer(name);if(usedContainerCells(a)+itemCells(ref)>fieldContainerLimit(name))return false;if(name==='rig'&&!canStoreInRig(ref))return false;if(name==='pockets'&&!canStoreInPocket(ref))return false;return true}
  function itemAmmoDescriptor(ref){const d=itemDef(ref);if(!d)return'';if(d.category==='magazine'){const n=magazineRounds(ref),cap=magazineCapacity(ref),top=magazineTopRound(ref);return `${n}/${cap} RD${top?' // '+(C[top]?.name||top):' // EMPTY'}`;}if(d.category==='ammo')return `${ammoRounds(ref)}/${d.stackRounds||60} ROUNDS`;return''}
  function fieldActionLabel(ref){const item=itemDef(ref)||{};if(item.category==='weapon'||item.category==='gear')return'EQUIP';if(item.category==='magazine')return'MANAGE';if(item.category==='ammo')return'LOAD';if(sceneMode==='bunker')return'';if(item.category==='medical')return'USE';if(item.category==='food')return'USE';if(item.category==='throwable')return'THROW';return''}
  function tacticalItemCell(ref,index,container){const id=itemId(ref),item=C[id]||{name:id,rarity:'common',category:'misc',weight:0};const action=fieldActionLabel(ref),secondary=sceneMode==='bunker'?'STASH':'DROP',desc=itemAmmoDescriptor(ref),cells=itemCells(ref);return `<article class="t-item ${item.rarity||'common'} ${cells>1?'multi-cell':''}" draggable="true" data-field-container="${container}" data-field-index="${index}" title="Drag between rig, pockets and backpack"><img src="${itemIcon(ref)}" alt=""><div><span>${(item.category||'ITEM').toUpperCase()}${cells>1?' // '+cells+' CELLS':''}</span><b>${item.name}</b><small>${desc||Number(itemWeight(ref)).toFixed(2)+' KG'}</small></div><div class="t-item-actions">${action?`<button data-field-use="${container}:${index}">${action}</button>`:''}<button class="danger-lite" data-field-drop="${container}:${index}">${secondary}</button></div></article>`}
  function renderContainerGrid(elId,items,capacity,container,emptyLabel){const el=$(elId);if(!el)return;const cells=[];for(let i=0;i<items.length;i++){const ref=items[i],span=itemCells(ref);cells.push(tacticalItemCell(ref,i,container));for(let n=1;n<span;n++)cells.push(`<div class="t-occupied-cell"><span>LINKED</span></div>`)}while(cells.length<capacity)cells.push(`<div class="t-empty-cell"><span>${String(cells.length+1).padStart(2,'0')}</span></div>`);el.innerHTML=cells.slice(0,capacity).join('');el.dataset.targetContainer=container;el.classList.toggle('is-empty',!items.length);if(!capacity)el.innerHTML=`<div class="empty-grid">${emptyLabel||'NO CONTAINER EQUIPPED'}</div>`}
  function bindTacticalInventory(){document.querySelectorAll('[data-field-use]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();const [c,i]=b.dataset.fieldUse.split(':');useFieldContainerItem(c,Number(i))}));document.querySelectorAll('[data-field-drop]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();const [c,i]=b.dataset.fieldDrop.split(':');dropFieldContainerItem(c,Number(i))}));document.querySelectorAll('[data-field-container]').forEach(el=>{el.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/deadhaul-item',JSON.stringify({container:el.dataset.fieldContainer,index:Number(el.dataset.fieldIndex)}));e.dataTransfer.effectAllowed='move'});el.addEventListener('dblclick',()=>{const c=el.dataset.fieldContainer,i=Number(el.dataset.fieldIndex);if(c==='backpack'){const ref=fieldContainer(c)[i],target=canMoveToFieldContainer(ref,'rig')?'rig':canMoveToFieldContainer(ref,'pockets')?'pockets':null;if(target)moveFieldItem(c,i,target)}else moveFieldItem(c,i,'backpack')})});document.querySelectorAll('.t-container-grid[data-target-container]').forEach(zone=>{zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('drag-over')});zone.addEventListener('dragleave',()=>zone.classList.remove('drag-over'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drag-over');try{const d=JSON.parse(e.dataTransfer.getData('text/deadhaul-item'));moveFieldItem(d.container,d.index,zone.dataset.targetContainer)}catch{}})})}
  function moveFieldItem(from,index,to){if(from===to)return;const a=fieldContainer(from),b=fieldContainer(to),ref=a[index];if(!ref)return;if(!canMoveToFieldContainer(ref,to)){toast(to==='rig'?'ITEM DOES NOT FIT OR RIG IS FULL':to==='pockets'?'POCKETS FULL / ITEM TOO LARGE':'BACKPACK FULL');return}a.splice(index,1);b.push(ref);if(sceneMode==='raid')recalcWeight();else A.saveLoadout?.(equipment).catch(err=>console.warn('safehouse container save failed',err));renderInventory();playUiClick(true)}
  async function usePreparedContainerItem(container,index){const bag=fieldContainer(container),ref=bag[index],id=itemId(ref),item=C[id];if(!id||!item)return;if(item.category==='magazine')return openMagazineManager(container,index);if(item.category==='ammo')return useAmmoContainerItem(container,index);const slot=gearSlotForItem(id);if(!slot){toast('THIS ITEM IS READY FOR RAID // USE IT ON THE SURFACE');return}if(isArmorPlate(id)&&!isPlateCarrier(equipment.armor)){toast('INSTALL A PLATE CARRIER FIRST');return}if(isArmorPlate(id)&&equipment.front_plate&&equipment.back_plate){toast('FRONT/BACK PLATES FULL — UNEQUIP ONE FIRST');return}if(slot==='armor'&&isPlateCarrier(equipment.armor)&&(equipment.front_plate||equipment.back_plate)){toast('REMOVE FRONT/BACK PLATES BEFORE CHANGING ARMOR');return}const remainingWeight=preparedWeight()-itemWeight(ref);if(['backpack','rig','armor'].includes(slot)&&remainingWeight>capacityWith(slot,id)){toast('PREPARED LOADOUT IS TOO HEAVY FOR THAT GEAR');return}if(slot==='rig'){const remain=usedContainerCells(preparedRig())-(container==='rig'?itemCells(ref):0);if(remain>rigSlotCount(id)){toast('EMPTY RIG CELLS BEFORE EQUIPPING A SMALLER RIG');return}}if(slot==='backpack'){const remain=usedContainerCells(preparedBag())-(container==='backpack'?itemCells(ref):0);if(remain>backpackSlotCount(id)){toast('EMPTY BACKPACK CELLS BEFORE EQUIPPING A SMALLER PACK');return}}try{const old=equipment[slot];bag.splice(index,1);if(old){const rec=await A.addInventoryItem(old);currentStash().unshift(rec)}equipment[slot]=id;await A.saveLoadout(equipment);if(WEAPONS[id]){initWeaponState(id);activeWeaponSlot=slot}await refreshGearAfterChange(slot);renderInventory();playUiClick(true);toast(item.name.toUpperCase()+' EQUIPPED')}catch(err){console.error(err);toast('LOADOUT UPDATE FAILED // '+(err.message||err),3000);await reloadStashData();equipment={...(playerData.loadout||equipment)};renderInventory()}}
  function useFieldContainerItem(container,index){if(sceneMode==='bunker')return usePreparedContainerItem(container,index);if(container==='backpack')return useOrEquipItem(index);const a=fieldContainer(container),ref=a[index],id=itemId(ref);if(!id)return;if(isMagazine(ref))return openMagazineManager(container,index);if(isAmmo(ref))return useAmmoContainerItem(container,index);if(usedContainerCells(fieldItems)+itemCells(ref)>backpackSlotCount()){toast('BACKPACK NEEDS ENOUGH FREE CELLS TO USE / EQUIP');return}a.splice(index,1);fieldItems.push(ref);recalcWeight();renderInventory();useOrEquipItem(fieldItems.length-1)}
  async function dropFieldContainerItem(container,index){if(sceneMode==='bunker'){await unpackPrepared(container,index);if(inventoryOpen)renderInventory();return}const a=fieldContainer(container);if(index<0||index>=a.length)return;const ref=a[index],id=itemId(ref),item=C[id];a.splice(index,1);recalcWeight();renderInventory();const f=currentCamera?.getForwardRay().direction||new BABYLON.Vector3(0,0,1),p=playerBody?.position?.clone()||BABYLON.Vector3.Zero();const pos=[p.x+f.x*.95,.18,p.z+f.z*.95];await spawnLoose(currentScene,id,pos,null,item?.category==='weapon'?.8:1,ref);playUiClick(true);toast((item?.name||id).toUpperCase()+' DROPPED')}
  function currentInventoryContainers(inBunker=sceneMode==='bunker'){return inBunker?[['rig',preparedRig()],['pockets',preparedPockets()],['backpack',preparedBag()]]:[['rig',fieldRigItems],['pockets',fieldPocketItems],['backpack',fieldItems]]}
  function findItemLocatorByUid(uid,inBunker=sceneMode==='bunker'){for(const [container,arr] of currentInventoryContainers(inBunker)){const index=arr.findIndex(x=>typeof x==='object'&&x?.uid===uid);if(index>=0)return{container,index,arr,ref:arr[index]}}return null}
  function ensureMutableItemAt(container,index){const arr=fieldContainer(container),raw=arr[index];if(!raw)return null;const ref=normalizeItemRef(raw,true);if(ref!==raw)arr[index]=ref;return ref}
  function allLooseAmmo(caliber,inBunker=sceneMode==='bunker'){const out=[];for(const [container,arr] of currentInventoryContainers(inBunker))for(let i=0;i<arr.length;i++){const ref=normalizeItemRef(arr[i],true),d=itemDef(ref);if(d?.category==='ammo'&&d.caliber===caliber&&ammoRounds(ref)>0){arr[i]=ref;out.push({container,index:i,arr,ref,id:itemId(ref),rounds:ammoRounds(ref)})}}return out}
  function looseAmmoCount(ammoId,inBunker=sceneMode==='bunker'){return allLooseAmmo(C[ammoId]?.caliber,inBunker).filter(x=>x.id===ammoId).reduce((n,x)=>n+x.rounds,0)}
  function consumeLooseAmmo(ammoId,count=1,inBunker=sceneMode==='bunker'){let need=Math.max(0,Math.floor(count)),taken=0;for(const [container,arr] of currentInventoryContainers(inBunker)){for(let i=arr.length-1;i>=0&&need>0;i--){let ref=normalizeItemRef(arr[i],true);if(itemId(ref)!==ammoId||!isAmmo(ref))continue;arr[i]=ref;const n=Math.min(need,ammoRounds(ref));ref.rounds-=n;need-=n;taken+=n;if(ref.rounds<=0)arr.splice(i,1)}}if(inBunker)A.saveLoadout?.(equipment).catch(()=>{});else recalcWeight();return taken}
  function canCreateAmmoStack(ammoId,inBunker=sceneMode==='bunker'){const ref=makeAmmoStack(ammoId,1);for(const [container,arr] of currentInventoryContainers(inBunker)){if((container==='rig'&&canStoreInRig(ref)||container==='pockets'&&canStoreInPocket(ref)||container==='backpack')&&usedContainerCells(arr)+itemCells(ref)<=fieldContainerLimit(container))return container}return null}
  function returnLooseAmmo(ammoId,count=1,inBunker=sceneMode==='bunker'){let left=Math.max(0,Math.floor(count)),added=0;const d=C[ammoId];if(!d||d.category!=='ammo')return 0;for(const [,arr] of currentInventoryContainers(inBunker)){for(let i=0;i<arr.length&&left>0;i++){let ref=normalizeItemRef(arr[i],true);if(itemId(ref)!==ammoId||!isAmmo(ref))continue;arr[i]=ref;const space=Math.max(0,(d.stackRounds||60)-ammoRounds(ref)),n=Math.min(space,left);ref.rounds+=n;left-=n;added+=n}}while(left>0){const container=canCreateAmmoStack(ammoId,inBunker);if(!container)break;const n=Math.min(left,d.stackRounds||60),arr=fieldContainer(container);arr.push(makeAmmoStack(ammoId,n));left-=n;added+=n}if(inBunker)A.saveLoadout?.(equipment).catch(()=>{});else recalcWeight();return added}
  function magazineAmmoSummary(ref){const counts={};for(const a of ref?.contents||[])counts[a]=(counts[a]||0)+1;return Object.entries(counts).map(([a,n])=>`${C[a]?.name||a} ×${n}`).join(' • ')||'EMPTY'}
  function magazineManagerCurrent(){if(!magazineManagerRef)return null;const {container,index,uid}=magazineManagerRef,arr=fieldContainer(container);let ref=arr[index];if(uid&&(!ref||ref.uid!==uid)){const found=findItemLocatorByUid(uid);if(found){magazineManagerRef={...magazineManagerRef,container:found.container,index:found.index,uid};ref=found.ref}}if(!ref||!isMagazine(ref))return null;ref=normalizeItemRef(ref,true);fieldContainer(magazineManagerRef.container)[magazineManagerRef.index]=ref;return ref}
  function compatibleWeaponSlotsForMagazine(ref){return ['primary','secondary'].filter(slot=>WEAPONS[equipment[slot]]&&magazineCompatibleWithWeapon(ref,equipment[slot]))}
  function renderMagazineManager(){const ref=magazineManagerCurrent();if(!ref){closePanel('magazinePanel');return}const id=itemId(ref),d=C[id],cap=magazineCapacity(ref),rounds=magazineRounds(ref),cal=d.caliber,ammo=allLooseAmmo(cal);$('magManageName').textContent=d.name;$('magManageMeta').textContent=`${rounds}/${cap} ROUNDS // ${itemCells(ref)} CELL${itemCells(ref)>1?'S':''} // ${cal.toUpperCase()}`;$('magManageBar').style.width=(cap?rounds/cap*100:0)+'%';$('magManageContents').textContent=magazineAmmoSummary(ref);$('magAmmoSources').innerHTML=ammo.length?[...new Map(ammo.map(x=>[x.id,x])).values()].map(x=>{const kind=C[x.id]?.shellType||'';return `<article class="mag-ammo-source ${kind?'ammo-type-'+kind:''}"><div><span>${C[x.id]?.name||x.id}</span><b>${looseAmmoCount(x.id)} RD AVAILABLE</b></div><div><button type="button" data-mag-ammo="${x.id}" data-mag-count="1">LOAD 1</button><button type="button" data-mag-ammo="${x.id}" data-mag-count="5">LOAD 5</button><button type="button" data-mag-ammo="${x.id}" data-mag-count="999">FILL</button></div></article>`}).join(''):'<div class="empty-grid">NO COMPATIBLE LOOSE AMMO IN YOUR CONTAINERS</div>';const slots=compatibleWeaponSlotsForMagazine(ref);$('magInsertActions').innerHTML=slots.length?slots.map(slot=>{const wid=equipment[slot],current=weaponStates[wid]?.insertedMag||equipment._weaponMags?.[wid],r=current?magazineRounds(current):0,c=current?magazineCapacity(current):0;return `<button data-mag-insert="${slot}">INSERT → ${slot.toUpperCase()} <small>${C[wid]?.name||wid} // CURRENT ${r}/${c}</small></button>`}).join(''):'<div class="empty-grid">NO EQUIPPED WEAPON ACCEPTS THIS MAGAZINE</div>';document.querySelectorAll('[data-mag-ammo]').forEach(b=>b.addEventListener('click',()=>loadMagazineAmmo(b.dataset.magAmmo,Number(b.dataset.magCount||1))));document.querySelectorAll('[data-mag-insert]').forEach(b=>b.addEventListener('click',()=>insertManagedMagazine(b.dataset.magInsert)))}
  function closeMagazineManager(){const reopen=magazineManagerRef?.returnTo;magazineOpen=false;$('magazinePanel')?.classList.add('hidden');magazineManagerRef=null;if(reopen==='inventory'){inventoryOpen=true;renderInventory();$('inventoryPanel')?.classList.remove('hidden');setTimeout(()=>previewEngine?.resize(),0)}else if(reopen==='stash'){stashOpen=true;renderStashPanel();$('stashPanel')?.classList.remove('hidden')}else resumePointer()}
  function openMagazineManager(container,index){const ref=ensureMutableItemAt(container,index);if(!ref||!isMagazine(ref))return;const returnTo=inventoryOpen?'inventory':stashOpen?'stash':null;closeAllGameplayPanels();magazineManagerRef={container,index,uid:ref.uid,returnTo};magazineOpen=true;$('magazinePanel').classList.remove('hidden');renderMagazineManager();releasePointer();playUiClick(true)}
  function loadMagazineAmmo(ammoId,count=1){const ref=magazineManagerCurrent();if(!ref)return;const d=itemDef(ref),space=magazineCapacity(ref)-magazineRounds(ref);if(space<=0){toast('MAGAZINE FULL');return}const want=Math.min(space,Math.max(1,count)),taken=consumeLooseAmmo(ammoId,want);if(!taken){toast('NO '+(C[ammoId]?.name||ammoId).toUpperCase()+' AVAILABLE');return}for(let i=0;i<taken;i++)ref.contents.push(ammoId);if(sceneMode==='bunker')A.saveLoadout?.(equipment).catch(()=>{});else recalcWeight();renderMagazineManager();if(inventoryOpen)renderInventory();if(stashOpen)renderStashPanel();playUiClick(true)}
  function unloadMagazineRounds(count=1){const ref=magazineManagerCurrent();if(!ref||!magazineRounds(ref)){toast('MAGAZINE EMPTY');return}let n=Math.min(Math.max(1,count),magazineRounds(ref)),done=0;while(n-->0){const ammo=ref.contents[ref.contents.length-1];if(returnLooseAmmo(ammo,1)!==1)break;ref.contents.pop();done++}if(!done){toast('NO FREE SPACE FOR LOOSE AMMO');return}if(sceneMode==='bunker')A.saveLoadout?.(equipment).catch(()=>{});else recalcWeight();renderMagazineManager();if(inventoryOpen)renderInventory();playUiClick(true)}
  function storeRefInInventory(ref,preferred='rig',inBunker=sceneMode==='bunker'){if(!ref)return true;const order=[preferred,'pockets','backpack','rig'].filter((x,i,a)=>a.indexOf(x)===i);for(const name of order){const arr=inBunker?(name==='rig'?preparedRig():name==='pockets'?preparedPockets():preparedBag()):(name==='rig'?fieldRigItems:name==='pockets'?fieldPocketItems:fieldItems);if(usedContainerCells(arr)+itemCells(ref)>fieldContainerLimit(name))continue;if(name==='rig'&&!canStoreInRig(ref))continue;if(name==='pockets'&&!canStoreInPocket(ref))continue;arr.push(ref);return true}return false}
  function insertManagedMagazine(slot){const ref=magazineManagerCurrent(),wid=equipment[slot];if(!ref||!wid||!magazineCompatibleWithWeapon(ref,wid))return;const arr=fieldContainer(magazineManagerRef.container),idx=magazineManagerRef.index,old=weaponStates[wid]?.insertedMag||equipment._weaponMags?.[wid]||null;arr.splice(idx,1);if(old&&!storeRefInInventory(old,magazineManagerRef.container)){arr.splice(idx,0,ref);toast('NO SPACE TO EJECT CURRENT MAGAZINE');return}if(!weaponStates[wid])initWeaponState(wid);weaponStates[wid].insertedMag=ref;equipment._weaponMags[wid]=serializeItemRef(ref);activeWeaponSlot=slot;if(sceneMode==='bunker')A.saveLoadout?.(equipment).catch(()=>{});else recalcWeight();const returnTo=magazineManagerRef?.returnTo;magazineManagerRef={...magazineManagerRef,returnTo};closeMagazineManager();updateWeaponHud();playUiClick(true);toast(`${C[idForWeapon(wid)]?.name||C[wid]?.name||wid} // MAGAZINE INSERTED`)}
  function idForWeapon(wid){return wid}
  function useAmmoContainerItem(container,index){const arr=fieldContainer(container),ref=ensureMutableItemAt(container,index),id=itemId(ref),d=C[id],w=getActiveWeapon();if(!ref||!d)return;if(!w||!ammoCompatibleWithWeapon(ref,w.id)){toast('SELECT A COMPATIBLE WEAPON OR LOAD THIS AMMO INTO A MAGAZINE');return}if(w.feed==='detachable'){const mags=currentInventoryContainers().flatMap(([c,a])=>a.map((x,i)=>({c,i,x}))).filter(x=>isMagazine(x.x)&&magazineCompatibleWithWeapon(x.x,w.id)&&magazineRounds(x.x)<magazineCapacity(x.x));if(!mags.length){toast('NO COMPATIBLE MAGAZINE WITH FREE SPACE');return}openMagazineManager(mags[0].c,mags[0].i);return}if(weaponRoundCount(w)>=weaponCapacity(w)){toast('WEAPON FULL');return}const taken=consumeLooseAmmo(id,1);if(!taken)return;w.state.internalRounds.push(id);w.state.preferredAmmo=id;syncWeaponFeedToEquipment();if(sceneMode==='bunker')A.saveLoadout?.(equipment).catch(()=>{});else recalcWeight();renderInventory();updateWeaponHud();playUiClick(true);toast((C[id]?.name||id).toUpperCase()+' LOADED')}
  function renderInventory(){const inBunker=sceneMode==='bunker',bag=inBunker?preparedBag():fieldItems,rig=inBunker?preparedRig():fieldRigItems,pockets=inBunker?preparedPockets():fieldPocketItems,carryWeight=inBunker?preparedWeight():fieldWeight;if($('inventoryModeLabel'))$('inventoryModeLabel').textContent=inBunker?'// SAFEHOUSE LOADOUT':'// SURVIVOR LOADOUT';if($('inventoryTitle'))$('inventoryTitle').textContent=inBunker?'PLAYER INVENTORY':'FIELD INVENTORY';if($('inventoryTipText'))$('inventoryTipText').textContent='Drag items between containers. Magazines store real rounds; click MANAGE to load, unload or insert them.';for(const slot of ['head','hands','armor','front_plate','back_plate','rig','backpack','primary','secondary']){const el=$('equip-'+slot);if(el)el.textContent=C[equipment[slot]]?.name||'EMPTY'}renderEquipmentSlotActions();const w=getActiveWeapon(),rounds=w?weaponRoundCount(w):0,cap=w?weaponCapacity(w):0,spares=w&&weaponUsesMagazine(w.id)?compatibleLoadedMagazineCount(w.id,inBunker):null,ammoName=w?currentWeaponAmmoLabel(w):'';$('invWeaponName').textContent=w?C[equipment[activeWeaponSlot]]?.name:'UNARMED';$('invWeaponStats').textContent=w?`${ammoName} // ${rounds}/${cap} RD // ${spares!==null?spares+' LOADED SPARE MAGS':'INTERNAL FEED'}`:'NO WEAPON';const feed=$('activeFeedControls');if(feed){if(w&&w.feed==='detachable'){const m=w.state?.insertedMag,mid=itemId(m);feed.innerHTML=`<div><span>INSERTED MAG</span><b>${m?(C[mid]?.name||mid):'NO MAGAZINE'}</b><small>${m?magazineRounds(m)+' / '+magazineCapacity(m)+' RD // '+magazineAmmoSummary(m):'Weapon cannot fire until a compatible loaded magazine is inserted.'}</small></div><div><button id="manageInsertedMag" ${m?'':'disabled'}>EJECT + MANAGE</button><button id="ejectInsertedMag" ${m?'':'disabled'}>EJECT MAG</button></div>`;feed.querySelector('#manageInsertedMag')?.addEventListener('click',manageActiveMagazine);feed.querySelector('#ejectInsertedMag')?.addEventListener('click',()=>ejectActiveMagazine(false))}else if(w){feed.innerHTML=`<div><span>INTERNAL FEED</span><b>${rounds} / ${cap} ROUNDS</b><small>${currentWeaponAmmoLabel(w)}</small></div>`}else feed.innerHTML=''}$('bagCapacity').textContent=`${carryWeight.toFixed(1)} / ${bagCapacity()} KG // ${usedContainerCells(bag)}/${backpackSlotCount()} CELLS`;if($('rigCapacityText'))$('rigCapacityText').textContent=`${usedContainerCells(rig)} / ${rigSlotCount()} CELLS // ${C[equipment.rig]?.name||'NO RIG'}`;if($('pocketCapacityText'))$('pocketCapacityText').textContent=`${usedContainerCells(pockets)} / 4 CELLS`;renderContainerGrid('rigGrid',rig,rigSlotCount(),'rig','NO CHEST RIG EQUIPPED');renderContainerGrid('pocketGrid',pockets,4,'pockets','POCKETS EMPTY');renderContainerGrid('bagGrid',bag,backpackSlotCount(),'backpack','NO BACKPACK EQUIPPED');bindTacticalInventory();updateEquipmentPresentation()}

  function lootCard(ref,i,take=true){const id=itemId(ref),d=C[id]||{name:id,rarity:'common',category:'misc',weight:0,value:0},desc=itemAmmoDescriptor(ref);return `<article class="item-card ${d.rarity||'common'} ${d.category==='weapon'?'weapon':''}"><img class="item-thumb" src="${itemIcon(ref)}" alt=""><span>${(d.category||'ITEM').toUpperCase()}</span><b>${d.name||id}</b><small>${desc||itemWeight(ref).toFixed(2)+' KG'} // $${Math.round(itemValue(ref)).toLocaleString()}</small>${take?`<button data-take="${i}">TAKE</button>`:''}</article>`}
  function renderLoot(){if(!lootSource)return;$('lootSourceName').textContent=lootSource.name;$('lootWeight').textContent=`${fieldWeight.toFixed(1)} / ${bagCapacity()} KG`;$('lootSourceGrid').innerHTML=lootSource.items.length?lootSource.items.map((ref,i)=>lootCard(ref,i,true)).join(''):'<div class="empty-grid">EMPTY</div>';$('lootBagGrid').innerHTML=fieldItems.length?fieldItems.map((ref,i)=>lootCard(ref,i,false)).join(''):'<div class="empty-grid">BACKPACK EMPTY</div>';document.querySelectorAll('[data-take]').forEach(b=>b.addEventListener('click',()=>takeLootItem(Number(b.dataset.take))))}

  function autoStoreFieldItem(input){const id=itemId(input),item=C[id];if(!item)return false;const ref=normalizeItemRef(input,false);if(fieldWeight+itemWeight(ref)>bagCapacity())return false;if(canStoreInRig(ref)&&usedContainerCells(fieldRigItems)+itemCells(ref)<=rigSlotCount()){fieldRigItems.push(ref);return true}if(canStoreInPocket(ref)&&usedContainerCells(fieldPocketItems)+itemCells(ref)<=4){fieldPocketItems.push(ref);return true}if(usedContainerCells(fieldItems)+itemCells(ref)<=backpackSlotCount()){fieldItems.push(ref);return true}return false}
  function takeLootItem(index){if(!lootSource)return;const ref=lootSource.items[index],id=itemId(ref),item=C[id];if(!item)return;if(!autoStoreFieldItem(ref)){toast('NO AVAILABLE STORAGE');return}recalcWeight();lootSource.items.splice(index,1);playUiClick(true);renderLoot();toast(item.name.toUpperCase()+' SECURED')}
  function takeAllLoot(){if(!lootSource)return;let took=0;for(let i=lootSource.items.length-1;i>=0;i--){const ref=lootSource.items[i];if(autoStoreFieldItem(ref)){lootSource.items.splice(i,1);took++}}recalcWeight();renderLoot();if(took){playUiClick(true);toast(`${took} ITEMS SECURED`)}else toast('NO SPACE AVAILABLE')}
  async function refreshGearAfterChange(slot){if(playerWorldRig&&currentScene)await attachConfiguredGear(currentScene,playerWorldRig);if(slot==='hands'&&sceneMode==='raid'){if(fpRig){disposeFirstPersonIK();try{fpRig.root.dispose(false,true)}catch{}fpRig=null}await loadViewWeapon()}updateEquipmentPresentation()}
  function useOrEquipItem(index){const ref=fieldItems[index],id=itemId(ref),item=C[id];if(!item)return;if(item.category==='magazine')return openMagazineManager('backpack',index);if(item.category==='ammo')return useAmmoContainerItem('backpack',index);if(item.category==='weapon')return equipFromBag(index);if(item.category==='gear'){let slot=gearSlotForItem(id);if(!slot)return;if(isArmorPlate(id)&&!isPlateCarrier(equipment.armor)){toast('INSTALL A PLATE CARRIER FIRST');return}if(isArmorPlate(id)&&equipment.front_plate&&equipment.back_plate){toast('FRONT/BACK PLATES FULL — UNEQUIP ONE FIRST');return}const old=equipment[slot];let newCap=capacityWith(slot,id);let newWeight=fieldWeight-itemWeight(ref)+(old?(C[old]?.weight||0):0);if(slot==='armor'&&isPlateCarrier(equipment.armor)&&(equipment.front_plate||equipment.back_plate)){toast('REMOVE FRONT/BACK PLATES BEFORE CHANGING ARMOR');return}if(slot==='backpack'||slot==='rig'||slot==='armor'){newCap=capacityWith(slot,id);if(newWeight>newCap){toast('MOVE ITEMS BEFORE CHANGING STORAGE GEAR');return}if(slot==='rig'&&usedContainerCells(fieldRigItems)>rigSlotCount(id)){toast('EMPTY RIG CELLS BEFORE EQUIPPING A SMALLER RIG');return}if(slot==='backpack'&&usedContainerCells(fieldItems)>backpackSlotCount(id)){toast('EMPTY BACKPACK CELLS BEFORE EQUIPPING A SMALLER PACK');return}}equipment[slot]=id;fieldItems.splice(index,1);if(old)fieldItems.push(old);recalcWeight();renderInventory();refreshGearAfterChange(slot);toast(item.name.toUpperCase()+' EQUIPPED');return}if(item.category==='medical'){const heal={bandage:12,medkit:42,morphine:24,splint:18,antibiotic:10,blood_bag:55}[id]||10;performMedicalUse(index,id,heal);return}if(item.category==='throwable'){closePanel('inventoryPanel');throwGrenade();return}if(item.category==='food'){stamina=Math.min(100,stamina+({water_bottle:35,canned_beans:28,energy_bar:24,coffee:18}[id]||20));fieldItems.splice(index,1);recalcWeight();renderInventory();toast(item.name.toUpperCase()+' CONSUMED');return}}

  function equipFromBag(index){const ref=fieldItems[index],id=itemId(ref),w=WEAPONS[id];if(!w)return;const slot=w.slot,old=equipment[slot];equipment[slot]=id;fieldItems.splice(index,1);if(old&&C[old])fieldItems.push(old);recalcWeight();initWeaponState(id);activeWeaponSlot=slot;loadViewWeapon();renderInventory();refreshGearAfterChange(slot);toast(C[id].name.toUpperCase()+' EQUIPPED')}
  async function unequipBunkerSlot(slot){const id=equipment[slot];if(!id)return;if(slot==='armor'&&isPlateCarrier(id)&&(equipment.front_plate||equipment.back_plate)){toast('REMOVE FRONT/BACK PLATES FIRST');return}if(slot==='rig'&&preparedRig().length){toast('EMPTY THE CHEST RIG FIRST');return}if(slot==='backpack'&&preparedBag().length){toast('EMPTY THE BACKPACK FIRST');return}if(['backpack','rig','armor'].includes(slot)&&preparedWeight()>capacityWith(slot,null)){toast('EMPTY OR LIGHTEN YOUR LOADOUT FIRST');return}try{const rec=await A.addInventoryItem(id);currentStash().unshift(rec);equipment[slot]=null;await A.saveLoadout(equipment);if(slot===activeWeaponSlot)activeWeaponSlot=WEAPONS[equipment.primary]?'primary':WEAPONS[equipment.secondary]?'secondary':'primary';await refreshGearAfterChange(slot);renderInventory();playUiClick(true);toast((C[id]?.name||id).toUpperCase()+' MOVED TO STASH')}catch(err){console.error(err);toast('UNEQUIP FAILED // '+(err.message||err),3000)}}
  function unequipRaidSlot(slot){if(sceneMode!=='raid')return;const id=equipment[slot];if(!id)return;const item=C[id];if(slot==='armor'&&isPlateCarrier(id)&&(equipment.front_plate||equipment.back_plate)){toast('REMOVE FRONT/BACK PLATES FIRST');return}if(slot==='rig'&&fieldRigItems.length){toast('EMPTY CHEST RIG FIRST');return}if(slot==='backpack'&&fieldItems.length){toast('EMPTY BACKPACK FIRST');return}let newWeight=fieldWeight+(item?.weight||0),newCap=capacityWith(slot,null);if(newWeight>newCap){toast(slot==='backpack'||slot==='rig'||slot==='armor'?'MOVE ITEMS BEFORE REMOVING STORAGE GEAR':'BACKPACK OVERWEIGHT');return}fieldItems.push(id);equipment[slot]=null;recalcWeight();if(slot===activeWeaponSlot){activeWeaponSlot=WEAPONS[equipment.primary]?'primary':WEAPONS[equipment.secondary]?'secondary':'primary';loadViewWeapon()}renderInventory();refreshGearAfterChange(slot);toast((item?.name||id).toUpperCase()+' REMOVED')}
