  // ---------- SAFEHOUSE STASH / PREP / DISPLAY ----------
  function currentStash(){return Array.isArray(playerData?.inventory)?playerData.inventory:[]}
  function preparedWeight(){return allPreparedItems().reduce((n,ref)=>n+itemWeight(ref),0)}
  function displayEntryForRecord(rec){return safehouseConfig.display?.find(x=>String(x.recordId)===String(rec.id))}
  function sanitizeSafehouseDisplay(){const ids=new Set(currentStash().map(x=>String(x.id)));safehouseConfig.display=(safehouseConfig.display||[]).filter(x=>ids.has(String(x.recordId))).slice(0,8);saveSafehouseConfig()}
  function stashActionLabel(id){if(isArmorPlate(id))return 'INSTALL PLATE';if(gearSlotForItem(id))return'EQUIP';if(canStoreInRig(id)&&equipment.rig)return'PACK TACTICAL';return'PACK'}
  function stashCategoryForItem(id){const item=C[id]||{},m=gearMeta(id);if(WEAPONS[id]||item.category==='weapon')return'weapons';if(item.category==='magazine')return'magazines';if(item.category==='ammo')return'ammo';if(['plate','plateCarrier','softArmor','helmet'].includes(m.type))return'armor';if(m.type==='rig')return'rigs';if(m.type==='backpack')return'backpacks';if(item.category==='medical')return'medical';if(item.category==='valuable')return'valuables';if(['food','throwable'].includes(item.category))return'supplies';if(item.category==='gear')return'gear';return'misc'}
  function filteredStash(){const q=stashSearchTerm.trim().toLowerCase();return currentStash().filter(rec=>{const id=rec.item_id,item=C[id]||{};if(stashCategory!=='all'&&stashCategoryForItem(id)!==stashCategory)return false;if(!q)return true;return `${item.name||rec.item_name||id} ${id} ${item.category||''} ${stashCategoryForItem(id)}`.toLowerCase().includes(q)})}
  function stashCard(rec){const id=rec.item_id,item=C[id]||{name:rec.item_name||id,weight:rec.weight||0,value:rec.value||0,rarity:rec.rarity||'common',category:'misc'},shown=!!displayEntryForRecord(rec),ref=inventoryRecordRef(rec),desc=itemAmmoDescriptor(ref);return `<article class="item-card ${item.rarity||'common'} ${item.category==='weapon'?'weapon':''} ${shown?'displayed':''}"><img class="item-thumb" src="${itemIcon(id)}" alt=""><span>${(item.category||item.rarity||'item').toUpperCase()}</span><b>${item.name}</b><small>${desc?desc+' // ':''}${Number(itemWeight(ref)||item.weight||0).toFixed(2)} KG // $${Math.round(itemValue(ref)).toLocaleString()}</small><div class="item-actions"><button data-stash-primary="${rec.id}">${stashActionLabel(id)}</button><button class="display-action" data-stash-display="${rec.id}">${shown?'REMOVE DISPLAY':'DISPLAY'}</button></div></article>`}
  function preparedCell(ref,index,container){const id=itemId(ref),item=C[id]||{name:id,weight:0,rarity:'common',category:'misc'},desc=itemAmmoDescriptor(ref);return `<article class="t-item ${item.rarity||'common'}"><img src="${itemIcon(ref)}" alt=""><div><span>${(item.category||'ITEM').toUpperCase()}</span><b>${item.name}</b><small>${desc||Number(itemWeight(ref)).toFixed(2)+' KG'}</small></div><div class="t-item-actions">${isMagazine(ref)?`<button data-prep-manage="${container}:${index}">MANAGE</button>`:''}<button class="wide-action" data-unpack-container="${container}" data-unpack-index="${index}">STASH</button></div></article>`}
  function preparedGridHtml(items,limit,container){const cells=[];for(let i=0;i<items.length;i++){const ref=items[i];cells.push(preparedCell(ref,i,container));for(let n=1;n<itemCells(ref);n++)cells.push('<div class="t-occupied-cell"><span>LINKED</span></div>')}while(cells.length<limit)cells.push(`<div class="t-empty-cell"><span>${String(cells.length+1).padStart(2,'0')}</span></div>`);return cells.slice(0,limit).join('')||'<div class="empty-grid">NO STORAGE</div>'}
  function renderStashPanel(){sanitizeSafehouseDisplay();const all=currentStash(),inv=filteredStash();$('stashCount').textContent=stashCategory==='all'&&!stashSearchTerm?`${all.length} ITEMS`:`${inv.length} / ${all.length} ITEMS`;document.querySelectorAll('[data-stash-category]').forEach(b=>b.classList.toggle('active',b.dataset.stashCategory===stashCategory));$('stashGridGame').innerHTML=inv.length?inv.map(stashCard).join(''):`<div class="empty-grid">${all.length?'NO ITEMS IN THIS CATEGORY':'STASH EMPTY // EXTRACT WITH LOOT TO FILL IT'}</div>`;const slots=[['head','HEAD'],['hands','HANDS'],['armor','CARRIER / ARMOR'],['front_plate','FRONT PLATE'],['back_plate','BACK PLATE'],['rig','CHEST RIG'],['backpack','BACKPACK'],['primary','PRIMARY'],['secondary','SIDEARM']];$('stashEquipment').innerHTML=slots.map(([slot,label])=>`<div class="stash-equip-row"><span>${label}</span><b>${C[equipment[slot]]?.name||'EMPTY'}</b><button data-stash-unequip="${slot}" ${equipment[slot]?'':'disabled'}>UNEQUIP</button></div>`).join('');preparedBag();preparedRig();preparedPockets();$('preparedWeight').textContent=`${preparedWeight().toFixed(1)} / ${bagCapacity()} KG`;$('preparedRigMeta').textContent=`${usedContainerCells(preparedRig())}/${rigSlotCount()} CELLS // ${C[equipment.rig]?.name||'NO RIG'}`;$('preparedRigGrid').innerHTML=preparedGridHtml(preparedRig(),rigSlotCount(),'rig');$('preparedPocketMeta').textContent=`${usedContainerCells(preparedPockets())}/4 CELLS`;$('preparedPocketGrid').innerHTML=preparedGridHtml(preparedPockets(),4,'pockets');$('preparedBagMeta').textContent=`${usedContainerCells(preparedBag())}/${backpackSlotCount()} CELLS // ${C[equipment.backpack]?.name||'NO BACKPACK'}`;$('preparedGrid').innerHTML=preparedGridHtml(preparedBag(),backpackSlotCount(),'backpack');renderDisplaySlots();document.querySelectorAll('[data-stash-primary]').forEach(b=>b.addEventListener('click',()=>stashPrimaryAction(b.dataset.stashPrimary)));document.querySelectorAll('[data-stash-display]').forEach(b=>b.addEventListener('click',()=>toggleDisplayRecord(b.dataset.stashDisplay)));document.querySelectorAll('[data-stash-unequip]').forEach(b=>b.addEventListener('click',()=>unequipPersistent(b.dataset.stashUnequip)));document.querySelectorAll('[data-unpack-index]').forEach(b=>b.addEventListener('click',()=>unpackPrepared(b.dataset.unpackContainer,Number(b.dataset.unpackIndex))));document.querySelectorAll('[data-prep-manage]').forEach(b=>b.addEventListener('click',()=>{const [c,i]=b.dataset.prepManage.split(':');openMagazineManager(c,Number(i))}))}
  function renderDisplaySlots(){const slots=$('displaySlots');if(!slots)return;const byId=new Map(currentStash().map(x=>[String(x.id),x]));const display=safehouseConfig.display||[];slots.innerHTML=Array.from({length:8},(_,i)=>{const d=display[i],r=d&&byId.get(String(d.recordId));if(!r)return'<div class="display-slot empty">EMPTY</div>';return `<div class="display-slot"><img src="${itemIcon(r.item_id)}" alt=""><b>${C[r.item_id]?.name||r.item_name||r.item_id}</b></div>`}).join('')}
  async function reloadStashData(){playerData=await A.getPlayerData();return playerData}
  async function openStashPanel(){if(sceneMode!=='bunker')return;closeAllGameplayPanels();stashOpen=true;try{await reloadStashData();equipment={...(playerData.loadout||equipment)};preparedBag();preparedRig();preparedPockets()}catch(err){console.warn('stash refresh failed',err)}renderStashPanel();$('stashPanel').classList.remove('hidden');releasePointer()}
  function labelForSelect(id,value){const el=$(id);return el?.querySelector?.(`option[value="${value}"]`)?.textContent||String(value||'').toUpperCase()}
  function renderCustomizationPanel(){const theme=safehouseConfig.theme||'concrete',floor=safehouseConfig.floor||'sealed',lamp=safehouseConfig.lampColor||'white',decor=safehouseConfig.decor||'survival',clutter=safehouseConfig.clutter||'normal',light=Number(safehouseConfig.light??.82);if($('safehouseTheme'))$('safehouseTheme').value=theme;if($('safehouseFloor'))$('safehouseFloor').value=floor;if($('safehouseLampColor'))$('safehouseLampColor').value=lamp;if($('safehouseDecor'))$('safehouseDecor').value=decor;if($('safehouseClutter'))$('safehouseClutter').value=clutter;if($('safehouseLight'))$('safehouseLight').value=light;if($('safehouseLightValue'))$('safehouseLightValue').textContent=light.toFixed(2);if($('safehouseProfileName'))$('safehouseProfileName').textContent='NODE 17 // '+labelForSelect('safehouseDecor',decor);if($('customWallReadout'))$('customWallReadout').textContent=labelForSelect('safehouseTheme',theme);if($('customFloorReadout'))$('customFloorReadout').textContent=labelForSelect('safehouseFloor',floor);if($('customLightReadout'))$('customLightReadout').textContent=labelForSelect('safehouseLampColor',lamp)+' // '+light.toFixed(2);if($('customDecorReadout'))$('customDecorReadout').textContent=labelForSelect('safehouseDecor',decor)+' // '+clutter.toUpperCase()}
  function openCustomizationPanel(){if(sceneMode!=='bunker')return;closeAllGameplayPanels();customizationOpen=true;renderCustomizationPanel();$('customizationPanel')?.classList.remove('hidden');releasePointer();playUiClick(true)}
  function removeLocalStashRecord(id){const idx=currentStash().findIndex(x=>String(x.id)===String(id));if(idx>=0)return currentStash().splice(idx,1)[0];return null}
  async function stashPrimaryAction(recordId){const rec=currentStash().find(x=>String(x.id)===String(recordId));if(!rec)return;const id=rec.item_id,slot=gearSlotForItem(id);playUiClick();try{if(slot)await equipStashRecord(rec,slot);else await packStashRecord(rec)}catch(err){console.error(err);toast('STASH UPDATE FAILED // '+(err.message||err),3000);await reloadStashData();renderStashPanel()}}
  async function equipStashRecord(rec,slot){const id=rec.item_id,old=equipment[slot];if(isArmorPlate(id)&&!isPlateCarrier(equipment.armor)){toast('INSTALL A PLATE CARRIER FIRST');return}if(isArmorPlate(id)&&equipment.front_plate&&equipment.back_plate){toast('FRONT/BACK PLATES FULL — UNEQUIP ONE FIRST');return}if(slot==='armor'&&isPlateCarrier(equipment.armor)&&(equipment.front_plate||equipment.back_plate)){toast('REMOVE FRONT/BACK PLATES BEFORE CHANGING ARMOR');return}if(slot==='backpack'||slot==='rig'||slot==='armor'){const cap=capacityWith(slot,id);if(preparedWeight()>cap){toast('PREPARED LOADOUT IS TOO HEAVY FOR THAT STORAGE SETUP');return}if(slot==='rig'&&usedContainerCells(preparedRig())>rigSlotCount(id)){toast('EMPTY RIG CELLS BEFORE EQUIPPING A SMALLER RIG');return}if(slot==='backpack'&&usedContainerCells(preparedBag())>backpackSlotCount(id)){toast('EMPTY BACKPACK CELLS BEFORE EQUIPPING A SMALLER PACK');return}}await A.removeInventoryRecord(rec.id);removeLocalStashRecord(rec.id);if(old){const added=await A.addInventoryItem(old);currentStash().unshift(added)}equipment[slot]=id;await A.saveLoadout(equipment);if(WEAPONS[id]){initWeaponState(id);activeWeaponSlot=slot}await refreshGearAfterChange(slot);renderStashPanel();rebuildSafehouseDisplays(currentScene);playUiClick(true);toast((C[id]?.name||id).toUpperCase()+' EQUIPPED')}
  async function unequipPersistent(slot){const id=equipment[slot];if(!id)return;if(slot==='armor'&&isPlateCarrier(id)&&(equipment.front_plate||equipment.back_plate)){toast('REMOVE FRONT/BACK PLATES FIRST');return}if(slot==='rig'&&preparedRig().length){toast('EMPTY THE CHEST RIG FIRST');return}if(slot==='backpack'&&preparedBag().length){toast('EMPTY THE BACKPACK FIRST');return}if(['backpack','rig','armor'].includes(slot)&&preparedWeight()>capacityWith(slot,null)){toast('EMPTY OR LIGHTEN PREPARED LOADOUT FIRST');return}playUiClick();try{const rec=await A.addInventoryItem(id);currentStash().unshift(rec);equipment[slot]=null;await A.saveLoadout(equipment);if(slot===activeWeaponSlot)activeWeaponSlot=WEAPONS[equipment.primary]?'primary':WEAPONS[equipment.secondary]?'secondary':'primary';await refreshGearAfterChange(slot);renderStashPanel();rebuildSafehouseDisplays(currentScene);playUiClick(true);toast((C[id]?.name||id).toUpperCase()+' MOVED TO STASH')}catch(err){console.error(err);toast('UNEQUIP FAILED // '+(err.message||err),3000);await reloadStashData();renderStashPanel()}}
  async function packStashRecord(rec){const id=rec.item_id,item=C[id],ref=inventoryRecordRef(rec);if(preparedWeight()+itemWeight(ref)>bagCapacity()){toast('PREPARED LOADOUT OVERWEIGHT');return}let target='backpack';if(canStoreInRig(ref)&&usedContainerCells(preparedRig())+itemCells(ref)<=rigSlotCount())target='rig';else if(canStoreInPocket(ref)&&usedContainerCells(preparedPockets())+itemCells(ref)<=4)target='pockets';else if(usedContainerCells(preparedBag())+itemCells(ref)>backpackSlotCount()){toast('NO FREE STORAGE CELLS');return}await A.removeInventoryRecord(rec.id);removeLocalStashRecord(rec.id);(target==='rig'?preparedRig():target==='pockets'?preparedPockets():preparedBag()).push(ref);await A.saveLoadout(equipment);safehouseConfig.display=(safehouseConfig.display||[]).filter(x=>String(x.recordId)!==String(rec.id));saveSafehouseConfig();renderStashPanel();rebuildSafehouseDisplays(currentScene);playUiClick(true);toast((item?.name||id).toUpperCase()+' → '+target.toUpperCase())}
  async function unpackPrepared(container,index){const bag=container==='rig'?preparedRig():container==='pockets'?preparedPockets():preparedBag();if(index<0||index>=bag.length)return;const ref=bag[index],id=itemId(ref);playUiClick();try{const rec=await A.addInventoryItem(serializeItemRef(ref));currentStash().unshift(rec);bag.splice(index,1);await A.saveLoadout(equipment);if(stashOpen)renderStashPanel();if(inventoryOpen)renderInventory();rebuildSafehouseDisplays(currentScene);playUiClick(true);toast((C[id]?.name||id).toUpperCase()+' RETURNED TO STASH')}catch(err){console.error(err);toast('STASH UPDATE FAILED // '+(err.message||err),3000)}}
  function toggleDisplayRecord(recordId){const rec=currentStash().find(x=>String(x.id)===String(recordId));if(!rec)return;safehouseConfig.display=safehouseConfig.display||[];const idx=safehouseConfig.display.findIndex(x=>String(x.recordId)===String(recordId));if(idx>=0)safehouseConfig.display.splice(idx,1);else{if(safehouseConfig.display.length>=8){toast('DISPLAY WALL FULL');return}safehouseConfig.display.push({recordId:rec.id,itemId:rec.item_id})}saveSafehouseConfig();renderStashPanel();rebuildSafehouseDisplays(currentScene);playUiClick(true)}
  function autoDisplayBestLoot(){safehouseConfig.display=[...currentStash()].sort((a,b)=>Number(b.value||0)-Number(a.value||0)).slice(0,8).map(r=>({recordId:r.id,itemId:r.item_id}));saveSafehouseConfig();renderStashPanel();rebuildSafehouseDisplays(currentScene);playUiClick(true);toast('DISPLAY WALL UPDATED')}
  function clearDisplayLoot(){safehouseConfig.display=[];saveSafehouseConfig();renderStashPanel();rebuildSafehouseDisplays(currentScene);playUiClick(true)}
  function applySafehouseVisualConfig(){if(!safehouseSceneRefs)return;const themes={concrete:['#242a28','#101412'],olive:['#293128','#111711'],charcoal:['#1d2221','#0a0d0c'],rust:['#342823','#17100d']},floors={sealed:'#202624',dark:'#121716',olive:'#252d25',rust:'#31251f'},lamps={white:'#bfd4bd',warm:'#e0b078',green:'#80b77b',red:'#c75950'},t=themes[safehouseConfig.theme]||themes.concrete;try{safehouseSceneRefs.concrete.diffuseColor=BABYLON.Color3.FromHexString(t[0]);safehouseSceneRefs.dark.diffuseColor=BABYLON.Color3.FromHexString(t[1]);if(safehouseSceneRefs.floor)safehouseSceneRefs.floor.diffuseColor=BABYLON.Color3.FromHexString(floors[safehouseConfig.floor]||floors.sealed);const base=Number(safehouseConfig.light??.82);safehouseSceneRefs.hemi.intensity=(playerData.state?.has_generator?.48:.20)*base;safehouseSceneRefs.lamp.intensity=(playerData.state?.has_generator?1.65:.48)*base;safehouseSceneRefs.lamp.diffuse=BABYLON.Color3.FromHexString(lamps[safehouseConfig.lampColor]||lamps.white)}catch{}}
  async function rebuildSafehouseDecor(scene){if(sceneMode!=='bunker'||!scene||isDisposedSafe(scene))return;for(const r of safehouseCustomizationRoots){try{r.dispose(false,true)}catch{}}safehouseCustomizationRoots=[];const preset=safehouseConfig.decor||'survival',density=safehouseConfig.clutter||'normal';const sets={minimal:[['chair',[-7.7,0,-8.6],0]],survival:[['fridge',[-8.8,0,-9.6],0],['duffel_bag',[-7.4,0,-10.1],.4],['storage_crate',[-8.5,0,-7.6],0]],workshop:[['tool_cabinet',[-8.8,0,-9.5],Math.PI/2],['hand_truck',[-8.6,0,-7.5],.2],['pallet',[-4.1,0,-9.6],0]],armory:[['locker_bank',[-8.8,0,-9.2],Math.PI/2],['weapon_crate',[-7.0,0,-10.0],0],['ammo_can',[-5.4,0,-10.1],0]]};let list=[...(sets[preset]||sets.survival)];if(density==='sparse')list=list.slice(0,1);if(density==='dense')list=list.concat(preset==='workshop'?[['barrel',[-4.4,0,-7.7],0],['cardboard_box',[-5.1,0,-9.9],.2]]:[['cardboard_box',[-5.0,0,-9.8],.3],['barrel',[-4.3,0,-8.2],0]]);for(const [file,pos,ry] of list){try{const r=await loadModel(scene,file,pos,{rotationY:ry||0,collision:false,scale:file==='ammo_can'?.9:1});if(scene!==currentScene||isDisposedSafe(scene)){r.dispose(false,true);continue}safehouseCustomizationRoots.push(r)}catch(err){console.warn('safehouse decor load failed',file,err)}}}
  function displayModelForItem(id){if(WEAPONS[id])return WEAPONS[id].model;if(MODEL_CONFIG.gear?.[id])return MODEL_CONFIG.gear[id].file;return {bandage:'loot_bandage',medkit:'loot_medkit',morphine:'loot_morphine',water_bottle:'loot_water',canned_beans:'loot_food',ssd:'loot_ssd',gpu:'loot_gpu',keycard:'loot_keycard',wristwatch:'loot_watch',copper_wire:'loot_copper_wire',battery:'loot_battery',fuel_can:'loot_fuel_can',tool_case:'loot_tool_case',power_inverter:'loot_inverter',frag_grenade:'frag_grenade'}[id]||null}
  async function rebuildSafehouseDisplays(scene){if(sceneMode!=='bunker'||!scene||isDisposedSafe(scene))return;for(const r of safehouseDisplayRoots){try{r.dispose(false,true)}catch{}}safehouseDisplayRoots=[];sanitizeSafehouseDisplay();const byId=new Map(currentStash().map(x=>[String(x.id),x])),positions=[[6.55,.82,-8.05],[6.55,1.58,-8.05],[6.55,2.34,-8.05],[6.55,3.10,-8.05],[6.55,.82,-4.35],[6.55,1.58,-4.35],[6.55,2.34,-4.35],[6.55,3.10,-4.35]];for(let i=0;i<(safehouseConfig.display||[]).length;i++){const d=safehouseConfig.display[i],rec=byId.get(String(d.recordId));if(!rec)continue;const id=rec.item_id,pos=positions[i],file=displayModelForItem(id);if(file){try{const root=await loadModel(scene,file,pos,{rotationY:-Math.PI/2,collision:false,pickable:false,scale:WEAPONS[id]?0.55:(MODEL_CONFIG.gear?.[id]?0.48:0.7)});safehouseDisplayRoots.push(root);continue}catch{}}const plane=BABYLON.MeshBuilder.CreatePlane('displayCard_'+i,{width:.75,height:.75},scene);plane.position=new BABYLON.Vector3(...pos);plane.rotation.y=-Math.PI/2;plane.isPickable=false;const m=new BABYLON.StandardMaterial('displayCardMat_'+i,scene);m.diffuseTexture=new BABYLON.Texture(itemIcon(id),scene,true,false);m.emissiveColor=new BABYLON.Color3(.18,.22,.17);m.specularColor=BABYLON.Color3.Black();plane.material=m;safehouseDisplayRoots.push(plane)}}


  // ---------- INTERACTIONS ----------
  function addInteraction(mesh,prompt,fn,range=2.6,anchor=null){let point=anchor?(anchor instanceof BABYLON.Vector3?anchor.clone():new BABYLON.Vector3(...anchor)):null,bounds=null;if(!point){try{mesh?.computeWorldMatrix?.(true);for(const c of mesh?.getChildMeshes?.()||[])c.computeWorldMatrix?.(true);const b=mesh?.getHierarchyBoundingVectors?.(true);if(b?.min&&b?.max){bounds={min:b.min.clone(),max:b.max.clone()};point=b.min.add(b.max).scale(.5)}}catch{}}if(!point){const p=mesh?.getAbsolutePosition?.()||mesh?.position||BABYLON.Vector3.Zero();point=p.clone?.()||new BABYLON.Vector3(p.x||0,p.y||0,p.z||0)}const obj={mesh,prompt,fn,range,bounds,point,enabled:true};interactions.push(obj);return obj}
  function interactionDistance(i,o){if(i.bounds){const x=clamp(o.x,i.bounds.min.x,i.bounds.max.x),y=clamp(o.y,i.bounds.min.y,i.bounds.max.y),z=clamp(o.z,i.bounds.min.z,i.bounds.max.z);return BABYLON.Vector3.Distance(o,new BABYLON.Vector3(x,y,z))}return BABYLON.Vector3.Distance(o,i.point)}
  function updateInteraction(){const p=$('interactionPrompt');if(anyPanelOpen()||!playerBody||!currentCamera||playerDead){nearest=null;p.classList.add('hidden');return}nearest=null;let best=Infinity;const origin=currentCamera.position;for(const i of interactions){if(!i.enabled||!i.mesh||isDisposedSafe(i.mesh))continue;const d=interactionDistance(i,origin);if(d<=i.range&&d<best){best=d;nearest=i}}if(nearest){p.textContent='[ E ] '+nearest.prompt;p.classList.remove('hidden')}else p.classList.add('hidden')}

  function itemDescriptor(ref){const id=itemId(ref),d=C[id],m=gearMeta(id);if(!d)return'';if(d.category==='magazine')return `${d.capacity||0} RD // ${d.caliber?.toUpperCase()||''} // ${d.cells||1} CELL${(d.cells||1)>1?'S':''}`;if(d.category==='ammo')return `${d.caliber?.toUpperCase()||''}${d.shellType?' // '+d.shellType.toUpperCase():''} // STACK ${d.stackRounds||0}`;if(m.type==='rig')return `${m.slots||0} TACTICAL CELLS`;if(m.type==='backpack')return `${m.slots||0} CELLS // ${m.capacity||0} KG`;if(m.type==='plate')return `ARMOR LEVEL ${m.level||0}`;if(m.type==='plateCarrier')return `PLATE CARRIER // ${m.storage||0} KG SUPPORT`;if(m.type==='helmet')return `HELMET LEVEL ${m.level||0}`;return''}

  // ---------- ADMIN / TEST ITEM SPAWNER ----------
  function adminStashCount(id){return currentStash().reduce((n,r)=>n+(r.item_id===id?1:0),0)}
  function adminCategories(){return [...new Set(Object.values(C).map(x=>x.category||'misc'))].sort()}
  function populateAdminCategories(){const sel=$('adminCategory');if(!sel)return;const cur=sel.value||'all';sel.innerHTML='<option value="all">ALL ITEMS</option>'+adminCategories().map(c=>`<option value="${c}">${c.toUpperCase()}</option>`).join('');sel.value=[...sel.options].some(o=>o.value===cur)?cur:'all'}
  function adminSelectedDestination(){return $('adminDestination')?.value||'stash'}
  function renderAdminPanel(){if(!ADMIN_ENABLED)return;populateAdminCategories();const q=($('adminSearch')?.value||'').trim().toLowerCase(),cat=$('adminCategory')?.value||'all';const items=Object.entries(C).filter(([id,item])=>(cat==='all'||item.category===cat)&&(!q||id.toLowerCase().includes(q)||(item.name||'').toLowerCase().includes(q)||(item.category||'').toLowerCase().includes(q))).sort((a,b)=>String(a[1].category).localeCompare(String(b[1].category))||String(a[1].name).localeCompare(String(b[1].name)));if($('adminItemCount'))$('adminItemCount').textContent=`${items.length} / ${Object.keys(C).length} ITEMS`;if($('adminDestination')){const opt=$('adminDestination').querySelector('option[value="field"]');if(opt)opt.disabled=sceneMode!=='raid';if(sceneMode!=='raid'&&$('adminDestination').value==='field')$('adminDestination').value='stash'}$('adminItemGrid').innerHTML=items.map(([id,item])=>`<article class="admin-item-card ${item.rarity||'common'}"><img src="${itemIcon(id)}" alt=""><span>${(item.category||'ITEM').toUpperCase()} // ${id}</span><b>${item.name||id}</b><small>${itemWeight(id).toFixed(2)} KG // $${Math.round(itemValue(id)).toLocaleString()}${itemDescriptor(id)?'<br>'+itemDescriptor(id):''}</small><small class="admin-have">STASH: ${adminStashCount(id)}</small><button type="button" data-admin-give="${id}" ${adminBusy?'disabled':''}>GIVE ×${Number($('adminQuantity')?.value||1)}</button></article>`).join('')||'<div class="empty-grid">NO MATCHING ITEMS</div>';document.querySelectorAll('[data-admin-give]').forEach(b=>b.addEventListener('click',()=>adminGive([b.dataset.adminGive],Number($('adminQuantity')?.value||1))))}
  async function adminGive(ids,qty=1,destination=adminSelectedDestination()){if(!ADMIN_ENABLED||adminBusy)return;qty=clamp(Math.floor(Number(qty)||1),1,50);const expanded=[];for(const id of ids)for(let i=0;i<qty;i++)if(C[id])expanded.push(id);if(!expanded.length)return;adminBusy=true;renderAdminPanel();try{if(destination==='field'){if(sceneMode!=='raid'){toast('FIELD INJECTION ONLY WORKS DURING A RAID');return}let added=0;for(const id of expanded){if(autoStoreFieldItem(id)){added++;recalcWeight()}else break}recalcWeight();if(inventoryOpen)renderInventory();toast(`ADMIN // ${added}/${expanded.length} ITEMS ADDED TO FIELD STORAGE`,2400)}else{if(typeof A.addInventoryItems==='function')await A.addInventoryItems(expanded);else for(const id of expanded)await A.addInventoryItem(id);await reloadStashData();if(stashOpen)renderStashPanel();toast(`ADMIN // ${expanded.length} ITEMS ADDED TO STASH`,2400)}playUiClick(true)}catch(err){console.error('Admin item injection failed',err);toast('ADMIN GIVE FAILED // '+(err.message||err),3200)}finally{adminBusy=false;renderAdminPanel()}}
  function adminPreset(kind){const all=Object.keys(C),byCat=(...cats)=>all.filter(id=>cats.includes(C[id]?.category));if(kind==='all')return adminGive(all,1,'stash');if(kind==='weapons')return adminGive(byCat('weapon'),1,'stash');if(kind==='gear')return adminGive(byCat('gear'),1,'stash');if(kind==='medical')return adminGive(byCat('medical'),5,'stash');if(kind==='combat'){const ids=[];ids.push(...byCat('weapon'),...byCat('gear'));for(const id of byCat('magazine'))for(let i=0;i<5;i++)ids.push(id);for(const id of byCat('ammo'))for(let i=0;i<4;i++)ids.push(id);for(const id of byCat('medical'))for(let i=0;i<3;i++)ids.push(id);for(const id of byCat('throwable'))for(let i=0;i<4;i++)ids.push(id);return adminGive(ids,1,'stash')}}
  function openAdminPanel(){if(!ADMIN_ENABLED){toast('ADMIN PANEL DISABLED IN CONFIG');return}if(adminOpen)return;closeAllGameplayPanels();adminOpen=true;renderAdminPanel();$('adminPanel').classList.remove('hidden');releasePointer();setTimeout(()=>$('adminSearch')?.focus(),0)}
  function toggleAdminPanel(){adminOpen?closePanel('adminPanel'):openAdminPanel()}

  // ---------- INVENTORY / VITALS ----------
  function recalcWeight(){fieldWeight=allFieldItems().reduce((n,ref)=>n+itemWeight(ref),0);updateVitals()}
  function updateVitals(){$('healthBar').style.width=clamp(health,0,100)+'%';$('healthText').textContent=Math.round(health);$('staminaBar').style.width=clamp(stamina,0,100)+'%';$('staminaText').textContent=Math.round(stamina);$('weightText').textContent=hauledHeavy?`${fieldWeight.toFixed(1)} KG + HEAVY`:`${fieldWeight.toFixed(1)} / ${bagCapacity()} KG`;$('miniItemCount').textContent=`${allFieldItems().length} ITEMS`;if(!inventoryOpen)return;$('bagCapacity').textContent=`${fieldWeight.toFixed(1)} / ${bagCapacity()} KG // ${usedContainerCells(fieldItems)}/${backpackSlotCount()} CELLS`}
  function incomingSide(dir){if(!currentCamera||!dir)return'front';const f=currentCamera.getForwardRay().direction.clone();f.y=0;if(f.lengthSquared()<.001)return'front';f.normalize();const d=dir.clone();d.y=0;if(d.lengthSquared()<.001)return'front';d.normalize();return BABYLON.Vector3.Dot(d,f)<0?'front':'back'}
  function armorMitigationForHit(zone,dir){zone=(zone||'chest').toLowerCase();if(zone.includes('head')){const h=gearMeta(equipment.head);return h.type==='helmet'?(h.mitigation||0):0}if(zone.includes('chest')||zone.includes('pelvis')){let m=0;if(equipment.armor==='soft_armor')m=Math.max(m,.22);if(isPlateCarrier(equipment.armor)){m=Math.max(m,.08);const plateId=incomingSide(dir)==='front'?equipment.front_plate:equipment.back_plate;const pm=gearMeta(plateId);if(pm.type==='plate')m=Math.max(m,pm.mitigation||0)}return m}return 0}
  function damagePlayer(amount,source='HOSTILE FIRE',zone='chest',dir=null){if(playerDead)return;const mitigation=clamp(armorMitigationForHit(zone,dir),0,.82);const actual=Math.max(1,amount*(1-mitigation));if(mitigation>.05)toast(`ARMOR ABSORBED ${Math.round(mitigation*100)}% // ${String(zone).toUpperCase()}`,850);health=Math.max(0,health-actual);$('damageFlash').classList.add('hit');setTimeout(()=>$('damageFlash').classList.remove('hit'),120);updateVitals();if(health<=0)playerDeath(source)}
  function playerDeath(cause){if(playerDead)return;playerDead=true;fireHeld=false;actionBusy=false;stopFpAction();clearActionProp();setViewWeaponVisible(true);stopTimer();releasePointer();$('interactionPrompt').classList.add('hidden');const duration=raidStart?Math.floor((Date.now()-raidStart)/1000):0;$('deathCause').textContent=`Killed by ${cause}. All field loot was lost.`;$('deathStats').innerHTML=`<div><span>DURATION</span><b>${formatTime(duration)}</b></div><div><span>LOOT LOST</span><b>${allFieldItems().length}</b></div><div><span>ZONE</span><b>${MAPS[selectedMapId]?.name||'SURFACE'}</b></div>`;$('deathOverlay').classList.remove('hidden')}

  // ---------- WEAPONS / BALLISTICS ----------
  function initWeaponState(id){const w=WEAPONS[id];if(!w)return;if(weaponStates[id])return;if(w.feed==='detachable'){let mag=equipment._weaponMags?.[id];if(mag&&!magazineCompatibleWithWeapon(mag,id))mag=null;weaponStates[id]={insertedMag:mag?normalizeItemRef(mag,true):null,internalRounds:[],preferredAmmo:w.ammo}}else{const rounds=Array.isArray(equipment._internalAmmo?.[id])?equipment._internalAmmo[id].filter(a=>C[a]?.category==='ammo'&&C[a]?.caliber===w.caliber).slice(-w.mag):[];weaponStates[id]={insertedMag:null,internalRounds:[...rounds],preferredAmmo:rounds[rounds.length-1]||w.ammo}}
  }
  function initWeapons(){weaponStates={};initWeaponState(equipment.primary);initWeaponState(equipment.secondary);activeWeaponSlot=WEAPONS[equipment.primary]?'primary':'secondary'}
  function getActiveWeapon(){const id=equipment[activeWeaponSlot];return WEAPONS[id]?{id,...WEAPONS[id],state:weaponStates[id]}:null}
